# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps, gap_labels

OPEN = parse_span("09:00-17:00")

def spans(*texts):
    return [parse_span(text) for text in texts]

class GapTests(unittest.TestCase):
    def test_lunch_gap(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            gap_labels(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_no_one_working_is_one_big_gap(self):
        self.assertEqual(find_gaps([], OPEN), [OPEN])
        self.assertEqual(
            gap_labels([], OPEN),
            ["gap 09:00-17:00 (480 min)"],
        )

    def test_full_coverage_has_no_gaps(self):
        worked = spans("09:00-13:00", "13:00-17:00")
        self.assertEqual(gap_labels(worked, OPEN), [])

    def test_overlaps_and_order_do_not_matter(self):
        worked = spans(
            "14:00-17:00", "09:00-12:30", "10:00-13:00"
        )
        self.assertEqual(
            gap_labels(worked, OPEN),
            ["gap 13:00-14:00 (60 min)"],
        )

    def test_gaps_at_both_ends_and_middle(self):
        worked = spans("10:00-11:00", "12:00-16:00")
        self.assertEqual(
            gap_labels(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 16:00-17:00 (60 min)",
            ],
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-10:00"), OPEN)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(16 * 60, 18 * 60)], OPEN)

if __name__ == "__main__":
    unittest.main()
